// === Check if we should send email (60-day rule) ===
// Input 1: Customers from Split Out
// Input 2: All rows from Google Sheet (sent email history)

const customers = $('Split Out Customers1').all();
const sheetRows = $('Read Sent Email History').all();

// Build a map of email -> last sent date from sheet
const emailHistory = {};
for (const row of sheetRows) {
  const email = String(row.json.Email || row.json.email || '').trim().toLowerCase();
  const lastSent = row.json['Last Email Sent Date'] || row.json.last_email_sent_date || null;
  if (email && lastSent) {
    emailHistory[email] = lastSent;
  }
}

const today = new Date();
const sixtyDaysAgo = new Date(today);
sixtyDaysAgo.setDate(today.getDate() - 60);

const output = [];

for (const item of customers) {
  const c = item.json || {};
  const email = String(c.email || '').trim().toLowerCase();

  if (!email) continue; // Skip if no email

  const lastSentStr = emailHistory[email] || null;
  let shouldSendEmail = false;

  if (!lastSentStr) {
    // Never emailed before
    shouldSendEmail = true;
  } else {
    const lastSentDate = new Date(lastSentStr);
    if (!isNaN(lastSentDate.getTime()) && lastSentDate < sixtyDaysAgo) {
      shouldSendEmail = true;
    }
  }

  if (shouldSendEmail) {
    output.push({
      json: {
        ...c,
        lastEmailDate: lastSentStr || null
      }
    });
  }
}

return output;
